/// <summary>
/// Allow create, delete or edit based inventlocation text 
/// </summary>
private void enableNewAndDeleteButton()
{
    FormDataSource custPickingSequence_ds = element.datasource(FormDataSourceStr(METCSDCustPickingSequence, METCSDCustPickingSequence));
    custPickingSequence_ds.allowDelete(InventLocationLookup.text() ? true : false);
    custPickingSequence_ds.allowCreate(InventLocationLookup.text() ? true : false);
    custPickingSequence_ds.allowEdit(InventLocationLookup.text() ? true : false);
    
}

        /// <summary>
        /// init datasource
        /// </summary>
        public void init()
        {
            super();

            //add range as inventlocation from the selected filter
            metCSDCustPickingSequence_ds.query().dataSourceTable(tableNum(METCSDCustPickingSequence)).
                    addRange(fieldNum(METCSDCustPickingSequence, InventLocationId)).value(queryValue(InventLocationLookup.text()));

            element.enableNewAndDeleteButton();          
        }

        /// <summary>
        /// init value CSD Cust picking sequence
        /// </summary>
        public void initValue()
        {
            super();

            metCSDCustPickingSequence.SequenceNumber = METCSDCustPickingSequence::LastCustPickingSequenceNum(InventLocationLookup.text()) + 10;
        }

            /// <summary>
            /// Perform lookup and bring customer account with the csd warehouse
            /// </summary>
            /// <param name = "_formControl">formcontrol</param>
            /// <param name = "_filterStr">filter string</param>
            public void lookup(FormControl _formControl, str _filterStr)
            {
                SysTableLookup sysTableLookup = SysTableLookup::newParameters(tablenum(CustTable), _formControl);
                Query                   query = new Query();
                QueryBuildDataSource    queryBuildInventLocationDS, queryBuildCustTableDS;

                queryBuildCustTableDS = query.addDataSource(tableNum(CustTable));
                queryBuildInventLocationDS = queryBuildCustTableDS.addDataSource(tableNum(InventLocation));
                queryBuildInventLocationDS.joinMode(JoinMode::InnerJoin);
                queryBuildInventLocationDS.relations(false);
                queryBuildInventLocationDS.addLink(fieldNum(CustTable, InventLocation), fieldNum(InventLocation, InventLocationId));
                queryBuildInventLocationDS.addRange(fieldNum(InventLocation, METCSDWarehouse)).value(SysQuery::value(NoYes::Yes));
                sysTableLookup.addLookupfield(fieldNum(CustTable, AccountNum));
                sysTableLookup.parmQuery(query);

                sysTableLookup.performFormLookup();
            }

/// <summary>
/// perform lookup on inventlocationId
/// </summary>
public void lookup()
{
    Query query = new Query();
    
    SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(InventLocation), this);
    QueryBuildDataSource queryBuildInventLocationDS = query.addDataSource(tableNum(InventLocation));
    queryBuildInventLocationDS.addRange(fieldNum(InventLocation, METCSDWarehouse)).value(queryValue(NoYes::Yes));
    sysTableLookup.addLookupfield(fieldNum(InventLocation, InventLocationId), true);
    sysTableLookup.addLookupfield(fieldNum(InventLocation, Name));
    
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

        /// <summary>
        /// Add range on datasource post inventlocation modification
        /// </summary>
        /// <returns>true or false</returns>
        public boolean modified()
        {
            boolean ret;
        
            ret = super();

            if (ret)
            {
                QueryBuildDataSource custPickingSequenceDS = METCSDCustPickingSequence_ds.query().dataSourceTable(tableNum(METCSDCustPickingSequence));
                custPickingSequenceDS.clearRanges();
                custPickingSequenceDS.addRange(fieldNum(METCSDCustPickingSequence, InventLocationId)).value(InventLocationLookup.text());
                
                element.enableNewAndDeleteButton();
                METCSDCustPickingSequence_ds.executeQuery();
            }
        
            return ret;
        }
